css:
.banrep-sim-container {
    padding: 24px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.banrep-sim-header {
    position: relative;
    background: linear-gradient(135deg, #0b1d3a 0%, #1a2744 100%);
    color: #ffffff;
    border-radius: 6px;
    padding: 28px 32px;
    margin-bottom: 24px;
    overflow: hidden;
}
.banrep-sim-header-accent {
    position: absolute;
    top: 0; right: 0;
    width: 8px; height: 100%;
    background: linear-gradient(180deg, #fcd116 0%, #fcd116 33%, #003893 33%, #003893 66%, #ce1126 66%, #ce1126 100%);
}
.banrep-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
}
.banrep-sim-subtitle {
    color: #aab8d0;
    font-size: 0.9rem;
    margin: 0;
}
.banrep-sim-period-counter {
    background: #ffffff;
    border-left: 4px solid #003893;
    padding: 12px 20px;
    margin-bottom: 20px;
    font-size: 0.95rem;
    font-weight: 600;
    color: #1a2744;
    border-radius: 0 4px 4px 0;
}
.banrep-sim-period-counter span {
    margin-right: 6px;
}
.banrep-sim-briefing {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 6px;
    padding: 22px;
    margin-bottom: 22px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
}
.banrep-sim-briefing-title {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #003893;
    margin-bottom: 12px;
}
.banrep-sim-briefing-text {
    color: #333f5a;
    font-size: 0.95rem;
    line-height: 1.55;
    margin-bottom: 18px;
}
.banrep-sim-macro-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    padding-top: 14px;
    border-top: 1px solid #eef1f7;
}
.banrep-sim-macro-card {
    background: #f8fafd;
    border-radius: 4px;
    padding: 12px 14px;
    border-left: 3px solid #003893;
}
.banrep-sim-macro-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #6b7794;
    margin-bottom: 4px;
}
.banrep-sim-macro-value {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a2744;
}
.banrep-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 22px;
}
.banrep-sim-status-card {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 6px;
    padding: 18px 16px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
    border-top: 3px solid #1a2744;
}
.banrep-sim-status-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6b7794;
    margin-bottom: 6px;
}
.banrep-sim-status-value {
    font-size: 1.4rem;
    font-weight: 700;
    color: #1a2744;
}
.banrep-sim-controls {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 6px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
}
.banrep-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #003893;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 2px solid #eef1f7;
}
.banrep-sim-control-row {
    margin-bottom: 14px;
    display: grid;
    grid-template-columns: 1fr 160px;
    align-items: center;
    gap: 12px;
}
.banrep-sim-control-row label {
    font-size: 0.88rem;
    color: #333f5a;
    font-weight: 500;
    margin: 0;
}
.banrep-sim-controls input[type="number"] {
    background: #ffffff;
    border: 1px solid #c7d0e0;
    color: #1a2744;
    border-radius: 4px;
    padding: 8px 10px;
    width: 100%;
    font-size: 0.95rem;
}
.banrep-sim-controls input[type="number"]:focus {
    outline: none;
    border-color: #003893;
    box-shadow: 0 0 0 3px rgba(0,56,147,0.12);
}
.banrep-sim-controls button#nextPeriodBtn {
    background: #003893;
    border: none;
    color: #ffffff;
    padding: 10px 22px;
    font-weight: 600;
    letter-spacing: 0.02em;
    border-radius: 4px;
    margin-right: 10px;
    margin-top: 8px;
    transition: background 0.2s ease;
}
.banrep-sim-controls button#nextPeriodBtn:hover {
    background: #002a6d;
}
.banrep-sim-controls button#undoBtn {
    margin-top: 8px;
}
.banrep-sim-hint {
    background: #fff9e6;
    border-left: 4px solid #fcd116;
    padding: 14px 18px;
    margin-bottom: 22px;
    border-radius: 0 4px 4px 0;
    font-size: 0.92rem;
    color: #5a4c0a;
}
.banrep-sim-history {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 6px;
    padding: 18px;
    margin-bottom: 22px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
    overflow-x: auto;
}
.banrep-sim-history table {
    margin: 0;
    font-size: 0.9rem;
}
.banrep-sim-history th {
    color: #003893;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #003893;
}
.banrep-sim-chart {
    background: #ffffff;
    border: 1px solid #d9e0ec;
    border-radius: 6px;
    padding: 20px;
    height: 360px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.06);
}
@media (max-width: 768px) {
    .banrep-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .banrep-sim-macro-grid { grid-template-columns: repeat(2, 1fr); }
    .banrep-sim-control-row { grid-template-columns: 1fr; }
    .banrep-sim-header h1 { font-size: 1.15rem; }
}

