(function() {
    'use strict';

    class BanRepAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Política Monetaria del Banco de la República';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    tasaBanrep: 13.25,
                    inflacion: 11.4,
                    pib: 1.1,
                    trm: 4650,
                    descLabel: 'round1_desc'
                },
                {
                    tasaBanrep: 12.25,
                    inflacion: 9.3,
                    pib: 1.6,
                    trm: 4420,
                    descLabel: 'round2_desc'
                },
                {
                    tasaBanrep: 10.50,
                    inflacion: 7.2,
                    pib: 2.3,
                    trm: 4180,
                    descLabel: 'round3_desc'
                },
                {
                    tasaBanrep: 8.75,
                    inflacion: 5.4,
                    pib: 3.1,
                    trm: 4050,
                    descLabel: 'round4_desc'
                }
            ];
        }

        // Helper: framework translator, safe before init
        _t(key) {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t(key)
                : key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 18000,
                    deuda: 42000,
                    ebitdaAcumulado: 0,
                    valorEmpresa: 85000,
                    ventasBase: 60000,
                    ebitdaHistory: [],
                    cashHistory: [],
                    valorHistory: [],
                    // performance.* is the shape the Express reporting/grading layer
                    // (results_utils.php: express_extractMetrics / express_compute_grade)
                    // reads for the instructor dashboard and LTI grade passback.
                    performance: { overallScore: 0, grade: '—' }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    precio: 5,
                    inversion: 2000,
                    mezcla: 40,
                    cobertura: 30
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const precio = document.getElementById('precioInput');
            const inversion = document.getElementById('inversionInput');
            const mezcla = document.getElementById('mezclaInput');
            const cobertura = document.getElementById('coberturaInput');
            if (precio)    decisions.precio    = parseFloat(precio.value);
            if (inversion) decisions.inversion = parseFloat(inversion.value);
            if (mezcla)    decisions.mezcla    = parseFloat(mezcla.value);
            if (cobertura) decisions.cobertura = parseFloat(cobertura.value);

            if (isNaN(decisions.precio) || decisions.precio < -10 || decisions.precio > 30) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('precio_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.inversion) || decisions.inversion < 0 || decisions.inversion > 20000) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('inversion_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.mezcla) || decisions.mezcla < 0 || decisions.mezcla > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('mezcla_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.cobertura) || decisions.cobertura < 0 || decisions.cobertura > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('cobertura_warning'), 'warning');
                return false;
            }
            // NOTE: validateDecisions is side-effect-free on the briefing UI.
            // (Previously it re-rendered the briefing here, which fought the
            // post-submit update and contributed to the shown/graded mismatch.)
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const macro = this.ROUNDS[idx];
            const ds = state.domainState;

            // Demand elasticity: higher price -> fewer units; lower rate -> more demand
            const priceEffect = 1 - (d.precio / 100) * 0.9;
            const rateEffect  = 1 + (12.0 - macro.tasaBanrep) * 0.015;
            const pibEffect   = 1 + (macro.pib - 2.0) * 0.03;
            const volumen     = Math.max(0.55, priceEffect * rateEffect * pibEffect);

            const ventas = ds.ventasBase * volumen * (1 + d.precio / 100);

            // Imported inputs: TRM hurts margins unless hedged
            const costoImportado = ventas * 0.35;
            const trmBase = 4200;
            const trmShock = (macro.trm - trmBase) / trmBase;
            const expCobertura = d.cobertura / 100;
            const costoCambiario = costoImportado * trmShock * (1 - expCobertura);
            const primaCobertura = costoImportado * 0.015 * expCobertura;

            const margenOperativo = ventas * 0.28 - costoCambiario - primaCobertura;

            // Financing: short-term debt repriced at current BanRep + spread
            const spread = 4.5;
            const tasaCorto = (macro.tasaBanrep + spread) / 100;
            const tasaLargo = 0.125; // fixed legacy long-term
            const deudaCorto = ds.deuda * (d.mezcla / 100);
            const deudaLargo = ds.deuda * (1 - d.mezcla / 100);
            const gastoFinanciero = deudaCorto * tasaCorto + deudaLargo * tasaLargo;

            // CapEx reduces cash but boosts future ventasBase
            const capex = d.inversion;
            const retornoCapex = capex * 0.08 * rateEffect;

            const ebitda = margenOperativo - gastoFinanciero * 0.3; // operating portion
            const utilidad = margenOperativo - gastoFinanciero - capex * 0.1;

            ds.cash += utilidad - capex + retornoCapex;
            ds.ebitdaAcumulado += ebitda;
            ds.ventasBase = ds.ventasBase + retornoCapex * 0.6;

            // Firm value via simple EBITDA multiple adjusted by rate environment
            const multiplo = Math.max(4.5, 9.5 - (macro.tasaBanrep - 4) * 0.35);
            ds.valorEmpresa = Math.max(0, ebitda * multiplo + ds.cash - ds.deuda + 40000);

            ds.ebitdaHistory.push(Math.round(ebitda));
            ds.cashHistory.push(Math.round(ds.cash));
            ds.valorHistory.push(Math.round(ds.valorEmpresa));

            // ── Platform score (0-100) + letter grade ─────────────────────────
            // Written into domainState.performance so the Express reporting layer
            // (express_extractMetrics / express_extractHistory / express_compute_grade)
            // records a real score and LTI grade instead of nothing / 0.
            const valueComp  = Math.max(0, Math.min(1, (ds.valorEmpresa - 60000) / 80000)); // 60k->0, 140k->1
            const ebitdaComp = Math.max(0, Math.min(1, ds.ebitdaAcumulado / 70000));        // 0->0, 70k->1
            const overallScore = Math.round(100 * (0.6 * valueComp + 0.4 * ebitdaComp));
            let grade = 'F';
            if (overallScore >= 85) grade = 'A';
            else if (overallScore >= 70) grade = 'B';
            else if (overallScore >= 55) grade = 'C';
            else if (overallScore >= 40) grade = 'D';
            ds.performance = { overallScore: overallScore, grade: grade };

            const results = {
                period: state.currentPeriod,
                tasaBanrep: macro.tasaBanrep,
                ventas: Math.round(ventas),
                ebitda: Math.round(ebitda),
                gastoFinanciero: Math.round(gastoFinanciero),
                utilidad: Math.round(utilidad),
                valorEmpresa: Math.round(ds.valorEmpresa),
                costoCambiario: Math.round(costoCambiario),
                // Mirror the score into results too (covers the history-extractor
                // fallback paths results.overallScore / results.score).
                overallScore: overallScore,
                score: overallScore,
                grade: grade
            };

            // Advance the briefing to the round the player will actually be graded
            // on next. The framework increments state.currentPeriod AFTER this
            // method returns, so the next round's index is currentPeriod (0-based)
            // i.e. (currentPeriod - 1) + 1. Done synchronously (no timer) so the
            // briefing never renders ahead of / behind the round counter.
            this._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });

            return results;
        }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            const briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.descLabel);

            const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
            set('tasaBanrepDisplay', round.tasaBanrep.toFixed(2) + '%');
            set('inflacionDisplay',  round.inflacion.toFixed(1) + '%');
            set('pibDisplay',        round.pib.toFixed(1) + '%');
            set('trmDisplay',        '$' + round.trm.toLocaleString() + ' COP');
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay',   'domainState.cash',          (v) => '$' + Math.round(v).toLocaleString() + ' M');
            uiManager.bind('deudaDisplay',  'domainState.deuda',         (v) => '$' + Math.round(v).toLocaleString() + ' M');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaAcumulado', (v) => '$' + Math.round(v).toLocaleString() + ' M');
            uiManager.bind('valorDisplay',  'domainState.valorEmpresa',  (v) => '$' + Math.round(v).toLocaleString() + ' M');

            // The framework's undo() rolls back state + counter but never calls the
            // adapter, so the (unbound) briefing/macro panel would stay on the stale
            // round. Re-render it from the restored currentPeriod on the next tick,
            // after the framework's synchronous undo has run.
            const self = this;
            const undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function () {
                    setTimeout(function () {
                        const live = (window.mySimulation && window.mySimulation.state)
                            ? window.mySimulation.state : { currentPeriod: 1 };
                        self._updateBriefing(live);
                    }, 0);
                });
            }
        }

        getChartConfig() {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            return {
                ebitdaChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                type: 'bar',
                                label: t('chart_ebitda'),
                                data: [],
                                backgroundColor: 'rgba(0,56,147,0.75)',
                                borderColor: '#003893',
                                borderWidth: 1,
                                yAxisID: 'y'
                            },
                            {
                                type: 'line',
                                label: t('chart_valor'),
                                data: [],
                                borderColor: '#ce1126',
                                backgroundColor: 'rgba(206,17,38,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_title') },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y:  { beginAtZero: true, position: 'left',  title: { display: true, text: t('chart_axis_ebitda') } },
                            y1: { beginAtZero: true, position: 'right', title: { display: true, text: t('chart_axis_valor') }, grid: { drawOnChartArea: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const labels = state.domainState.ebitdaHistory.map((_, i) => 'R' + (i + 1));
            return {
                ebitdaChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ebitdaHistory },
                        { data: state.domainState.valorHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            if (!history.length) return {};

            const last = history[history.length - 1];
            const ds = (last && last.domainState) ? last.domainState : {};
            const valorFinal  = Math.round(ds.valorEmpresa || (last.results && last.results.valorEmpresa) || 0);
            const ebitdaTotal = Math.round(ds.ebitdaAcumulado || 0);
            const overallScore = (ds.performance && typeof ds.performance.overallScore === 'number')
                ? ds.performance.overallScore : 0;

            let ratingKey = 'rating_principiante';
            if (overallScore >= 75) ratingKey = 'rating_excelente';
            else if (overallScore >= 50) ratingKey = 'rating_competente';

            const insights = [];
            if (ebitdaTotal < 30000) insights.push(t('insight_low_ebitda'));
            if (valorFinal > 120000) insights.push(t('insight_excellent'));
            if (!insights.length) insights.push(t('insight_stable'));

            const money = (v) => '$' + Math.round(v).toLocaleString() + ' M';
            const out = {};
            out[t('sum_score')]  = overallScore + ' / 100';
            out[t('sum_valor')]  = money(valorFinal);
            out[t('sum_ebitda')] = money(ebitdaTotal);
            out[t('sum_rating')] = t(ratingKey);
            out[t('sum_reco')]   = insights;
            return out;
        }

        getHint(state, results) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            let msg = null;
            if (results) {
                if (results.ebitda < 0) msg = t('hint_ebitda_neg');
                else if (results.costoCambiario > 2500) msg = t('hint_trm');
                else if (state.decisions.mezcla > 70 && results.tasaBanrep > 11) msg = t('hint_corto_plazo');
                else if (state.decisions.inversion > 10000 && results.tasaBanrep > 11) msg = t('hint_capex_alto');
            }
            // Surface the hint in the (previously unused) styled hint box so it is
            // persistent, not just an ephemeral host toast.
            const box = document.getElementById('hintBox');
            if (box) {
                if (msg) { box.textContent = '💡 ' + msg; box.style.display = 'block'; }
                else { box.textContent = ''; box.style.display = 'none'; }
            }
            return msg;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.tasaBanrep',      label: 'Tasa BanRep', i18nKey: 'col_tasa',     formatter: (v) => v.toFixed(2) + '%' },
                { key: 'decisions.precio',        label: 'Precio Δ%',   i18nKey: 'col_precio',   formatter: (v) => v + '%' },
                { key: 'decisions.inversion',    label: 'CapEx',        i18nKey: 'col_capex',    formatter: (v) => '$' + v.toLocaleString() + ' M' },
                { key: 'decisions.mezcla',       label: 'Corto %',      i18nKey: 'col_corto',    formatter: (v) => v + '%' },
                { key: 'decisions.cobertura',    label: 'Hedge %',      i18nKey: 'col_hedge',    formatter: (v) => v + '%' },
                { key: 'results.ebitda',          label: 'EBITDA',      i18nKey: 'col_ebitda',   formatter: (v) => '$' + v.toLocaleString() + ' M' },
                { key: 'results.gastoFinanciero', label: 'Gasto Fin.',  i18nKey: 'col_gasto_fin', formatter: (v) => '$' + v.toLocaleString() + ' M' },
                { key: 'results.valorEmpresa',    label: 'Valor',       i18nKey: 'col_valor',    formatter: (v) => '$' + v.toLocaleString() + ' M' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `Monetary Policy of Banco de la República`,
                    subtitle:           `Impact of interest-rate decisions on corporate operations`,
                    period_label:       `Round`,
                    period_of:          `of`,
                    briefing_heading:   `Macroeconomic Context`,
                    tasa_label:         `BanRep Rate`,
                    inflacion_label:    `Annual Inflation`,
                    pib_label:          `GDP Growth`,
                    trm_label:          `FX Rate (COP/USD)`,
                    caja_label:         `Cash`,
                    deuda_label:        `Total Debt`,
                    ebitda_label:       `Cumulative EBITDA`,
                    valor_label:        `Firm Value`,
                    decisions_heading:  `Period Decisions`,
                    precio_label:       `Price change (%)`,
                    inversion_label:    `CapEx (COP millions)`,
                    mezcla_label:       `Short-term debt (% of total)`,
                    cobertura_label:    `FX hedging (%)`,
                    submit_btn:         `Execute Round`,
                    undo_btn:           `Undo Round`,
                    precio_warning:     `Price change must be between -10% and 30%`,
                    inversion_warning:  `CapEx must be between 0 and 20,000`,
                    mezcla_warning:     `Short-term debt mix must be between 0% and 100%`,
                    cobertura_warning:  `Hedge ratio must be between 0% and 100%`,
                    hint_ebitda_neg:    `EBITDA is negative. The rate shock is squeezing margins — review pricing power and hedging.`,
                    hint_trm:           `FX losses are eating margin. Increase hedging ratio before the next round.`,
                    hint_corto_plazo:   `High short-term debt share in a restrictive cycle repriced your interest costs sharply.`,
                    hint_capex_alto:    `Heavy CapEx while BanRep holds rates high compresses free cash. Consider deferring investment.`,
